def transform(grid):
    points = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] != 7]
    if len(grid[0]) <= 5:
        points.sort()
    else:
        points.sort(key=lambda p: (p[1], p[0]))
    result = [row[:] for row in grid]
    for i, (r, c) in enumerate(points):
        result[r][c] = (2, 8, 5)[i % 3]
    return result
